func testSistemaToManyAddOpSisProdutos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Sistema
	var b, c, d, e Produto

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, sistemaDBTypes, false, strmangle.SetComplement(sistemaPrimaryKeyColumns, sistemaColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Produto{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, produtoDBTypes, false, strmangle.SetComplement(produtoPrimaryKeyColumns, produtoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*Produto{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddSisProdutos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if !queries.Equal(a.SisID, first.SisID) {
			t.Error("foreign key was wrong value", a.SisID, first.SisID)
		}
		if !queries.Equal(a.SisID, second.SisID) {
			t.Error("foreign key was wrong value", a.SisID, second.SisID)
		}

		if first.R.Sis != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Sis != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.SisProdutos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.SisProdutos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.SisProdutos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

func testSistemaToManySetOpSisProdutos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Sistema
	var b, c, d, e Produto

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, sistemaDBTypes, false, strmangle.SetComplement(sistemaPrimaryKeyColumns, sistemaColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Produto{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, produtoDBTypes, false, strmangle.SetComplement(produtoPrimaryKeyColumns, produtoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err = a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.SetSisProdutos(ctx, tx, false, &b, &c)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.SisProdutos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	err = a.SetSisProdutos(ctx, tx, true, &d, &e)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.SisProdutos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.SisID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.SisID) {
		t.Error("want c's foreign key value to be nil")
	}
	if !queries.Equal(a.SisID, d.SisID) {
		t.Error("foreign key was wrong value", a.SisID, d.SisID)
	}
	if !queries.Equal(a.SisID, e.SisID) {
		t.Error("foreign key was wrong value", a.SisID, e.SisID)
	}

	if b.R.Sis != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Sis != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Sis != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}
	if e.R.Sis != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}

	if a.R.SisProdutos[0] != &d {
		t.Error("relationship struct slice not set to correct value")
	}
	if a.R.SisProdutos[1] != &e {
		t.Error("relationship struct slice not set to correct value")
	}
}

